import json

# Create 3x3 squares centered at each point
grid = [[0]*15 for _ in range(15)]
for point_r, point_c in [(0,0), (3,3), (6,6)]:
    # Fill 3x3 around each point (clamped to grid)
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            r, c = point_r + dr, point_c + dc
            if 0 <= r < 15 and 0 <= c < 15:
